const q = $('Reaction Router').first().json;

const rows = $('Find Expense').all()
  .map(i => i.json).flatMap(j => Array.isArray(j) ? j : [j])
  .filter(r => r && r.expense_id);

const row = rows[0] || null;

// A reaction on anything else - a chatbot answer, someone else's summary -
// lands here too. Silence is the right answer to those, and the only case
// where silence is right.
// The undo deletes the row outright, so a second reaction on the same message
// finds nothing and lands here too - the rep has already been told it was
// removed, so there is nothing left to say.
if (!row) return [{ json: { action: 'ignore', expense_id: null, image_path: null, reply: '' } }];

const UNDO = ['\u{1F44E}', '\u274C', '\u2716', '\u274E', '\u{1F6AB}', '\u{1F645}', '\u{1F5D1}', '\u26D4'];
const isUndo = UNDO.some(e => q.emoji.includes(e));
const id = row.expense_id;

// They reacted to their own receipt with something that does not mean undo.
// Saying so beats staying quiet, which reads as "done" and leaves a receipt
// logged that they believe they cancelled.
if (!isUndo) {
  return [{ json: { action: 'note', expense_id: id,
    reply: '\u2139\uFE0F *' + id + '* is still logged.\n\n'
      + 'To remove it, react \u{1F44E} to that receipt message.' } }];
}

const WINDOW_MS = 24 * 60 * 60 * 1000;
if (Date.now() - new Date(row.processed_at).getTime() > WINDOW_MS) {
  return [{ json: { action: 'note', expense_id: id,
    reply: '\u23F3 *' + id + "* is more than 24 hours old, so I can't remove it now. "
      + 'Ask accounts to take it off.' } }];
}

return [{ json: { action: 'void', expense_id: id, image_path: row.image_path || null, reply: '' } }];

const m = $('WhatsApp Trigger').first().json.messages?.[0] || {};
const r = m.reaction || {};
const emoji = String(r.emoji || '');
const messageId = r.message_id || '';

// Removing a reaction arrives as an empty emoji. That is not a signal, and
// must not be read as one.
return [{ json: {
  proceed: !!messageId && emoji !== '',
  from: m.from || '',
  message_id: messageId,
  emoji,
} }];

const d = $('Build Row').first().json;
const num = v => parseFloat(v) || 0;
const fmt = n => 'PKR ' + num(n).toLocaleString('en-PK', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const items = Array.isArray(d.items) ? d.items : [];
const cP = Math.round(num(d.ai_confidence) * 100);
const cE = cP >= 85 ? '\u{1F7E2}' : cP >= 70 ? '\u{1F7E1}' : '\u{1F534}';

const itemLines = items.slice(0, 5)
  .map((it, i) => '  ' + (i + 1) + '. ' + it.description + ': ' + fmt(it.amount)).join('\n');
const more = items.length > 5 ? '\n  _...and ' + (items.length - 5) + ' more_' : '';

const msg = '\u2705 *Receipt Logged \u2014 Hi Tech Machinery*\n'
  + '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n'
  + '\u{1F3EA} *Vendor:* ' + (d.vendor_name || 'Unknown') + '\n'
  + '\u{1F4C5} *Date:* ' + (d.date || 'Unknown') + '\n'
  + '\u{1F4B5} *Subtotal:* ' + fmt(d.subtotal) + '\n'
  + (num(d.tax) > 0 ? '\u{1F9FE} *Tax:* ' + fmt(d.tax) + '\n' : '')
  + '\u{1F4B0} *Total:* *' + fmt(d.total) + '*\n'
  + '\u{1F3F7}\uFE0F *Category:* ' + (d.category || 'Other') + '\n'
  + '\u{1F4B3} *Payment:* ' + (d.payment_method || 'Unknown') + '\n'
  + (items.length ? '\n\u{1F4CB} *Items (' + items.length + '):*\n' + itemLines + more + '\n' : '')
  + '\n' + cE + ' *AI confidence:* ' + cP + '%\n'
  + '\u{1F194} *Expense ID:* ' + d.expense_id + '\n\n'
  // States the whole rule - which emoji, on which message, for how long -
  // because this is the only place the rep will ever read it.
  + '_Something wrong? React \u{1F44E} to *this* message within 24 hours and '
  + "I'll remove it. Then send the corrected photo._";

return [{ json: { message: msg, expense_id: d.expense_id } }];

const f = $('Parse OCR').first().json;
const g = $('Sender Gate').first().json;
const prep = $('Prep Save').first().json;
const dup = $('Is Content Dup?').first().json || {};

const uploaded = $('Upload to Storage').first();
const okUpload = uploaded && !uploaded.json?.error;

const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const CATS = ['Food','Fuel','Travel','Supplies','Utilities','Repairs','Other'];

return { json: {
  expense_id: prep.expense_id,
  vendor_name: f.vendor_name || null,
  date: f.date || null,
  receipt_number: f.receipt_number || null,
  payment_method: f.payment_method || null,
  tax_id: f.tax_id || null,
  category: CATS.includes(f.category) ? f.category : 'Other',
  currency: 'PKR',
  subtotal: num(f.subtotal),
  tax: num(f.tax),
  total: num(f.total),
  items: Array.isArray(f.items) ? f.items : [],
  is_receipt: true,
  ai_confidence: num(f.ai_confidence),

  // Persisted so the NEXT upload can be matched against it. Without this the
  // hash layer of the dedupe never fires, because nothing writes a hash.
  receipt_hash: dup.image_hash || null,

  // Same vendor/date/total as someone else's receipt, with no receipt number to
  // tell them apart. Not blocked - flagged for the accountant.
  ai_flag: dup.soft_dup_id
    ? 'POSSIBLE_DUPLICATE of ' + dup.soft_dup_id + ' (' + (dup.soft_dup_by || 'another employee') + ')'
    : (f.ai_flag || null),

  user_id: g.uid || null,
  sender_phone: g.from || null,
  employee_name: g.employee_name || null,
  department: g.department || null,
  status: 'logged',
  processed_at: new Date().toISOString(),
  image_path: okUpload ? prep.path : null,
} };

const f = $('Parse OCR').first().json;
const g = $('Sender Gate').first().json;
const b64 = $('Image to Base64').first().json.base64Image || '';
const mime = $('Image to Base64').first().json.mimeType || 'image/jpeg';

const path = g.storage_prefix + '/' + f.expense_id + '.jpg';
const buffer = Buffer.from(b64, 'base64');

// Rebuilt from the base64 rather than passed through as binary, so this node
// depends only on values that are already on the run - the same trick the web
// workflow uses in its Prep Save.
return {
  json: { uid: g.uid, expense_id: f.expense_id, path, mime },
  binary: { data: await this.helpers.prepareBinaryData(buffer, f.expense_id + '.jpg', mime) },
};

const f    = $('Parse OCR').first().json;
const me   = ($('Sender Gate').first().json.employee_name || '').trim().toLowerCase();
const hash = $('Hash Image').first().json.image_hash || null;
const norm = v => String(v ?? '').replace(/[\s\-\/]/g, '').toUpperCase();
const mine = norm(f.receipt_number);

const rows = $('Check Content Dup').all()
  .map(i => i.json).flatMap(j => Array.isArray(j) ? j : [j])
  .filter(r => r && r.expense_id);

let hard = null, soft = null;
for (const r of rows) {
  const theirs   = norm(r.receipt_number);
  const sameUser = (r.employee_name || '').trim().toLowerCase() === me;

  if (hash && r.receipt_hash && r.receipt_hash === hash) { hard = r; break; }  // 1
  if (mine && theirs) {                                                        // 2 & 3
    if (mine === theirs) { hard = r; break; }
    continue;                        // different receipt numbers = different receipts
  }
  if (sameUser) { hard = r; break; }                                           // 4
  soft = soft || r;                                                            // 5
}

return [{ json: {
  is_dup:      !!hard,
  dup_id:      hard ? hard.expense_id : null,
  image_hash:  hash,
  soft_dup_id: soft ? soft.expense_id : null,
  soft_dup_by: soft ? soft.employee_name : null,
}}];

const response = $input.item.json;

let rawText = '';
if (response.candidates?.[0]?.content?.parts) {
  rawText = response.candidates[0].content.parts
    .filter(p => p.text !== undefined).map(p => p.text).join('\n');
} else {
  rawText = response.text || response.message?.content || response.output || '';
}

const fence = String.fromCharCode(96);
const clean = rawText
  .replace(new RegExp(fence + '{3}json', 'gi'), '')
  .replace(new RegExp(fence + '{3}', 'gi'), '')
  .trim();

let receipt = null;
try {
  receipt = JSON.parse(clean);
} catch (e) {
  const match = clean.match(/[\{\[][\s\S]*[\}\]]/);
  if (match) {
    try { receipt = JSON.parse(match[0]); } catch (innerE) {}
  }
}

function normalizeCategory(raw) {
  const s = String(raw || '').toLowerCase().trim();
  const CANON = ['Food', 'Fuel', 'Travel', 'Supplies', 'Utilities', 'Repairs', 'Other'];
  if (/food|meal|restaurant|grocer|cafe|snack|lunch|dinner|breakfast|bakery|\btea\b|eat/.test(s)) return 'Food';
  if (/fuel|petrol|diesel|\bcng\b|gasol|filling station|gas station|\bpump\b/.test(s)) return 'Fuel';
  if (/travel|taxi|uber|careem|indrive|flight|\bair\b|hotel|\bfare\b|\bbus\b|train|toll|rickshaw|transport/.test(s)) return 'Travel';
  if (/suppl|stationer|office|hardware|\bpart\b|\btool|material|equipment/.test(s)) return 'Supplies';
  if (/utilit|electric|internet|wifi|\bphone\b|mobile|\bbill\b|water/.test(s)) return 'Utilities';
  if (/repair|mainten|service|\bfix\b|spare/.test(s)) return 'Repairs';
  const hit = CANON.find(x => x.toLowerCase() === s);
  return hit || 'Other';
}

const sd = $('Sender Gate').first().json;
const receiptHash = $('Hash Image').first().json.image_hash || null;
const expenseId = 'EXP-' + new Date().getFullYear() + '-'
  + Date.now().toString(36).toUpperCase()
  + Math.random().toString(36).slice(2, 6).toUpperCase();

const base = {
  expense_id: expenseId,
  receipt_hash: receiptHash,
  sender_phone: sd?.from || null,
  employee_name: sd?.employee_name || null,
  department: sd?.department || null,
  currency: 'PKR',
  processed_at: new Date().toISOString(),
};

if (!receipt || typeof receipt !== 'object' || receipt.is_receipt === false) {
  return { json: { ...base,
    status: 'rejected', ai_flag: 'REJECTED_NOT_RECEIPT', is_receipt: false,
    total: 0, subtotal: 0, tax: 0, items: [],
  } };
}

receipt.total = parseFloat(receipt.total) || 0;
receipt.subtotal = parseFloat(receipt.subtotal) || 0;
receipt.tax = parseFloat(receipt.tax) || 0;

if (receipt.subtotal === 0 && receipt.total > 0) {
  receipt.subtotal = parseFloat((receipt.total - receipt.tax).toFixed(2));
}

if (!Array.isArray(receipt.items)) receipt.items = [];
receipt.items = receipt.items.map(i => ({
  description: i.description || 'Item',
  qty: parseFloat(i.qty) || 1,
  unit_price: parseFloat(i.unit_price) || 0,
  amount: parseFloat(i.amount) || 0,
}));

return { json: { ...base,
  vendor_name: receipt.vendor_name || null,
  date: receipt.date || null,
  receipt_number: receipt.receipt_number || null,
  payment_method: receipt.payment_method || null,
  tax_id: receipt.tax_id || null,
  category: normalizeCategory(receipt.category),
  subtotal: receipt.subtotal,
  tax: receipt.tax,
  total: receipt.total,
  items: receipt.items,
  is_receipt: true,
  ai_confidence: parseFloat(receipt.ai_confidence) || 0.85,
  ai_flag: receipt.ai_flag || null,
  status: 'logged',
} };

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const keys = Object.keys(item.binary || {});
  const key = item.binary && item.binary.data ? 'data' : keys[0];

  if (!key) {
    item.json.base64Image = '';
    item.json.mimeType = 'image/jpeg';
    continue;
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, key);
  item.json.base64Image = buffer.toString('base64');
  item.json.mimeType = item.binary[key].mimeType || 'image/jpeg';
}

return items;

const g = $('Receipt Guard').first().json;

// Both lookups are best-effort (onError: continue), so they can hand back an
// error object, an empty array, or a single row. Flatten all three shapes.
const firstRow = (nodeName) => {
  const items = $(nodeName).all();
  if (!items.length) return {};
  const j = items[0].json;
  const row = Array.isArray(j) ? (j[0] || {}) : (j || {});
  return (row && !row.error && !row.message) ? row : {};
};

const wl = firstRow('Look Up Sender');   // wap_allowed_senders - the WhatsApp whitelist
const au = firstRow('Look Up App User'); // app_users - only if they also have a dashboard login

const uid = au.user_id || null;

return [{ json: {
  authorized: !!wl.phone,
  from: g.from,
  image_id: g.image_id,
  mime_type: g.mime_type,
  uid,
  // app_users is what the web uploader writes its name from, so it wins here.
  // wap_allowed_senders is hand-maintained and its casing drifts (sarim / ai
  // against Sarim / AI), which split one person into two people in the
  // dashboard depending on which channel they used. The whitelist name stays
  // as the fallback, for senders who have no dashboard login at all.
  employee_name: au.full_name || wl.employee_name || null,
  department: au.department || wl.department || null,

  // Storage RLS scopes reads to the folder named after the viewer's auth uid.
  // A sender with no dashboard login gets a phone-named folder, readable only
  // by accountants/admins - and it starts resolving to their own uid the day
  // their phone lands in app_users.
  storage_prefix: uid || ('whatsapp/' + g.from),
} }];

const msg = $('WhatsApp Trigger').first().json.messages?.[0] || {};
const from = msg.from || '';
const img = msg.image || {};
const mime = img.mime_type || '';
const size = img.file_size || 0;
const OK_MIME = ['image/jpeg', 'image/png', 'image/webp'];

// WhatsApp itself rejects images over 5 MB, so the size check is a floor in
// case Meta raises the cap - not the thing doing the real work.
if (!img.id) {
  return [{ json: { ok: false, from, reason: 'NO_IMAGE',
    reply: "\u274c I couldn't read that image. Please send the receipt photo again." } }];
}
if (!OK_MIME.includes(mime)) {
  return [{ json: { ok: false, from, reason: 'BAD_MIME',
    reply: '\u274c Unsupported file type. Send a JPG, PNG or WebP photo.' } }];
}
if (size > 10 * 1024 * 1024) {
  return [{ json: { ok: false, from, reason: 'TOO_LARGE',
    reply: '\u274c That image is too large. Max 10 MB.' } }];
}

return [{ json: {
  ok: true,
  from,
  image_id: img.id,
  mime_type: mime,
  caption: img.caption || '',
} }];

