{
  "type": "object",
  "properties": {
    "reply": {
      "type": "string",
      "description": "The formatted message shown in the web chat using single asterisks for bolding and emojis for bullet points."
    },
    "images": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "An array containing the extracted image URLs matching the machines mentioned in the reply."
    },
    "cacheable": {
      "type": "boolean",
      "description": "true ONLY if (1) the message is self-contained AND (2) the answer is stable and reusable. false for follow-ups ('that one','a smaller one','the price'), bare confirmations, OR a 'couldn't find / double-check the model' fallback. When unsure, false."
    }
  },
  "required": ["reply", "images", "cacheable"]
}

